import { marked } from "marked";
import { wrapHtml } from "./template";
import { stripFrontmatter } from "./text";

/**
 * The render half of the pipeline, ported from the Smitty `share` CLI
 * (`render.js`). `marked` in GFM mode drives the exact same HTML as today's
 * `share` (the review renderer — unified + rehype — is deliberately untouched,
 * so published output keeps byte-level fidelity). The PDF is generated by
 * puppeteer, imported lazily so cold routes never pay for Chromium.
 */

/** Render markdown to the clean (bar-free) HTML document used for the PDF.
 *  Leading YAML frontmatter is stripped first — `marked` would otherwise render
 *  it as a giant setext heading (the closing `---` underlines the metadata). */
export function toHtml(markdown: string, title: string): string {
  const bodyHtml = marked.parse(stripFrontmatter(markdown), { gfm: true, breaks: false, async: false });
  return wrapHtml(bodyHtml, title);
}

/**
 * Render an HTML document to a PDF (A4, GitHub-style margins, backgrounds on) —
 * the same puppeteer settings the `share` CLI used. Puppeteer is dynamically
 * imported here so it (and the Chromium download) only loads when a publish
 * actually renders a PDF; unit tests mock `puppeteer` so Chrome never launches.
 */
export async function toPdf(html: string): Promise<Uint8Array> {
  const { default: puppeteer } = await import("puppeteer");
  const browser = await puppeteer.launch({
    headless: true,
    args: ["--no-sandbox", "--disable-setuid-sandbox"],
  });

  try {
    const page = await browser.newPage();
    // Preserve the `share` CLI behavior exactly: wait for network idle so any
    // remote images in a published doc are loaded before the PDF snapshot.
    // puppeteer's types conservatively exclude `networkidle*` from setContent's
    // waitUntil, but the runtime honors it — hence the checked cast on the value.
    await page.setContent(html, { waitUntil: "networkidle0" as unknown as "load" });
    return await page.pdf({
      format: "A4",
      margin: { top: "1in", right: "0.75in", bottom: "1in", left: "0.75in" },
      printBackground: true,
    });
  } finally {
    await browser.close();
  }
}
